def chunk_file(file_path: str, content: str) -> List[CodeChunk]:
    norm_path = file_path.replace("\\", "/").lower()

    if norm_path.endswith(".py"):
        return parse_python_ast(content, file_path)
    elif norm_path.endswith((".js", ".jsx", ".mjs", ".cjs")):
        return parse_js_ts_regex(content, file_path, "javascript")
    elif norm_path.endswith((".ts", ".tsx", ".mts", ".cts")):
        return parse_js_ts_regex(content, file_path, "typescript")
    elif norm_path.endswith((".md", ".txt", ".json", ".yaml", ".yml", ".toml", ".sql", ".sh", ".bash", ".html", ".css")):
        lang = norm_path.split(".")[-1]
        return parse_fallback_text(content, file_path, lang)
    else:
        return []

class ClonedRepo:
    def __init__(self, temp_dir: Optional[str], repo_path: str, is_temp: bool = True):
        self.temp_dir = temp_dir
        self.repo_path = repo_path
        self.is_temp = is_temp

    def get_code_files(self) -> Dict[str, str]:
        """Walks repository and returns a map of {relative_path: content} for valid code files."""
        files_map: Dict[str, str] = {}
        for root, dirs, files in os.walk(self.repo_path):
            # Prune ignored directories in-place
            dirs[:] = [d for d in dirs if d not in IGNORED_DIRS and not d.startswith(".")]

            for file in files:
                ext = os.path.splitext(file)[1].lower()
                if ext in IGNORED_EXTENSIONS or file.startswith("."):
                    continue

                abs_file_path = os.path.join(root, file)
                rel_file_path = os.path.relpath(abs_file_path, self.repo_path).replace("\\", "/")

                # Read text safely
                try:
                    with open(abs_file_path, "r", encoding="utf-8", errors="ignore") as f:
                        content = f.read()
                    # Skip empty or excessively huge generated files (> 1MB)
                    if content.strip() and len(content) < 1_000_000:
                        files_map[rel_file_path] = content
                except Exception:
                    continue

        return files_map

    def cleanup(self):
