                    data = json.load(f)
                for item in data.get("chunks", []):
                    record = ChunkRecord(**item)
                    self._chunks[record.chunk_id] = record
                    self._repo_map[record.chunk_id] = record.repo_id
                for cid, vec in data.get("vectors", {}).items():
